/**
 * The DISTINCT-sunk row kernel must compete inside the strategy arbiter instead of capturing DISTINCT queries by ladder
 * position. The fixture is the regression shape: {@code SELECT DISTINCT ?b} over a star join whose third leg has a
 * large fan-out that only matters for existence — the factorized route collapses it to a per-key witness while a
 * positionally captured kernel enumerates every edge. Codegen stays off so the interpreter tier serves the kernel rung
 * deterministically (the compile threshold otherwise flips strategies mid-suite).
 */
public class LmdbNativeDistinctKernelArbitrationTest {

	private static final String EX = "http://example.com/";
	private static final String NATIVE_FLAG = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String DISTINCT_KERNEL_FLAG = "rdf4j.lmdb.kernelDistinct.enabled";
	private static final String STRATEGY_PROPOSAL_COSTS_METRIC = "nativeStrategyProposalCosts";
	private static final String STRATEGY_DECLINES_METRIC = "nativeStrategyDeclines";

	private static final String[] PROPERTIES = {
			NATIVE_FLAG,
			"rdf4j.lmdb.janinoCodegen.enabled",
			"rdf4j.lmdb.kernelInterpreter.enabled",
			"rdf4j.lmdb.costCalibration.enabled",
			"rdf4j.lmdb.parallel.enabled",
			"rdf4j.lmdb.parallel.threads",
			"rdf4j.lmdb.parallel.minWorkEstimate",
			"rdf4j.lmdb.parallel.startupWork",
			"rdf4j.lmdb.irKernelParallel.enabled",
			DISTINCT_KERNEL_FLAG,
			"rdf4j.lmdb.wcoj.enabled",
			"rdf4j.lmdb.factorizedRows.enabled",
			"rdf4j.lmdb.nativeBatch.enabled",
			"rdf4j.lmdb.packedFtree.enabled",
			"rdf4j.lmdb.prefixRun.enabled",
			"rdf4j.lmdb.adaptiveFilterPlacement.enabled",
			"rdf4j.lmdb.janinoCodegen.distinctDeadValueDemotion" };

	private static final int CARS = 60;
	private static final int PRED2_FANOUT = 50;

	@TempDir
	File dataDir;

	private final Map<String, String> previousProperties = new HashMap<>();
	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		for (String property : PROPERTIES) {
			previousProperties.put(property, System.getProperty(property));
		}
		System.setProperty(NATIVE_FLAG, "true");
		// Deterministic kernel engagement: interpreter tier only, no compile-threshold churn, no learned state.
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "false");
		System.setProperty("rdf4j.lmdb.kernelInterpreter.enabled", "true");
		System.setProperty("rdf4j.lmdb.costCalibration.enabled", "false");
		System.setProperty("rdf4j.lmdb.parallel.enabled", "false");

		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30));
		repository = new SailRepository(store);
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI car = vf.createIRI(EX, "Car");
			IRI pred1 = vf.createIRI(EX, "pred1");
			IRI pred2 = vf.createIRI(EX, "pred2");
			// Single transaction, deliberately (per-add autocommit wedges direct adjacency into a revision gap).
			conn.begin();
			for (int i = 0; i < CARS; i++) {
				IRI subject = vf.createIRI(EX, "car" + i);
				conn.add(subject, RDF.TYPE, car);
				conn.add(subject, pred1, vf.createIRI(EX, "b" + (i % 20)));
				for (int j = 0; j < PRED2_FANOUT; j++) {
					conn.add(subject, pred2, vf.createIRI(EX, "c" + i + "_" + j));
				}
			}
			conn.commit();
		}
		try {
			assertThat(store.awaitDirectAdjacencyReady(60, TimeUnit.SECONDS)).isTrue();
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new IllegalStateException(e);
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
		for (Map.Entry<String, String> property : previousProperties.entrySet()) {
			if (property.getValue() == null) {
				System.clearProperty(property.getKey());
			} else {
				System.setProperty(property.getKey(), property.getValue());
			}
		}
	}

	private static String distinctFanoutQuery() {
		return "PREFIX ex: <" + EX + ">\n"
				+ "SELECT DISTINCT ?b WHERE { ?a a ex:Car . ?a ex:pred1 ?b . ?a ex:pred2 ?c }";
	}

	@Test
	public void distinctKernelIsOfferedAsProposalNotPositionalCapture() {
		String query = distinctFanoutQuery();
		GenericPlanNode plan = explain(query);
		// The distinct kernel must show up as a priced proposal in the arbiter trace...
		assertThat(findMetric(plan, STRATEGY_PROPOSAL_COSTS_METRIC))
				.as("distinct kernel must be offered to the arbiter, not capture by position")
				.isNotNull()
				.contains("irKernelDistinct"); // compiled or interpreted variant, whichever tier is active
		// ...and the pre-fix positional capture recorded the *plain* kernel tag; that path must be gone.
		assertThat(findMetric(plan, "nativeExecutionPath"))
				.as("positional capture recorded the plain irKernel tag; an arbitrated winner carries a distinct tag")
				.isNotIn("irKernel", "irKernelInterpreted");
		assertThat(rows(query)).containsExactlyElementsOf(genericRows(query));
	}

	@Test
	public void killSwitchDisablesDistinctKernelAndRecordsDecline() {
		System.setProperty(DISTINCT_KERNEL_FLAG, "false");
		String query = distinctFanoutQuery();
		GenericPlanNode plan = explain(query);
		assertThat(findMetric(plan, STRATEGY_DECLINES_METRIC))
				.as("disabled distinct kernel must decline loudly")
				.isNotNull()
				.contains("irKernelDistinct:disabled");
		String path = findMetric(plan, "nativeExecutionPath");
		assertThat(path).isNotNull();
		assertThat(path).doesNotStartWith("irKernelDistinct");
		assertThat(rows(query)).containsExactlyElementsOf(genericRows(query));
	}

	@Test
	public void distinctKernelWinsWithDistinctTagWhenRivalsAreDisabled() {
		System.setProperty("rdf4j.lmdb.wcoj.enabled", "false");
		System.setProperty("rdf4j.lmdb.factorizedRows.enabled", "false");
		System.setProperty("rdf4j.lmdb.nativeBatch.enabled", "false");
		System.setProperty("rdf4j.lmdb.packedFtree.enabled", "false");
		System.setProperty("rdf4j.lmdb.prefixRun.enabled", "false");
		System.setProperty("rdf4j.lmdb.adaptiveFilterPlacement.enabled", "false");
		String query = distinctFanoutQuery();
		GenericPlanNode plan = explain(query);
		assertThat(findMetric(plan, "nativeExecutionPath"))
				.as("with every rival disabled the distinct kernel wins under its own interpreted tag")
				.isEqualTo("irKernelDistinctInterpreted");
		assertThat(rows(query)).containsExactlyElementsOf(genericRows(query));
	}

	@Test
	public void parallelDistinctKernelIsIndependentlyArbitrated() {
		System.setProperty("rdf4j.lmdb.parallel.enabled", "true");
		System.setProperty("rdf4j.lmdb.parallel.threads", "4");
		System.setProperty("rdf4j.lmdb.parallel.minWorkEstimate", "1");
		System.setProperty("rdf4j.lmdb.parallel.startupWork", "0");
		System.setProperty("rdf4j.lmdb.irKernelParallel.enabled", "true");
		System.setProperty("rdf4j.lmdb.wcoj.enabled", "false");
		System.setProperty("rdf4j.lmdb.factorizedRows.enabled", "false");
		System.setProperty("rdf4j.lmdb.nativeBatch.enabled", "false");
		System.setProperty("rdf4j.lmdb.packedFtree.enabled", "false");
		System.setProperty("rdf4j.lmdb.prefixRun.enabled", "false");
		System.setProperty("rdf4j.lmdb.adaptiveFilterPlacement.enabled", "false");

		String query = distinctFanoutQuery();
		GenericPlanNode plan = explain(query);
		assertThat(findMetric(plan, STRATEGY_PROPOSAL_COSTS_METRIC))
				.contains("irKernelDistinctParallelInterpreted=")
				.contains("irKernelDistinctInterpreted=");
		assertThat(findMetric(plan, "nativeExecutionPath")).contains("irKernelDistinctParallelInterpreted");
		assertThat(rows(query)).containsExactlyElementsOf(genericRows(query));
	}

	/**
	 * The dead-value demotion turns the fan-out enumeration into a keys-only existence witness; a key whose entire
	 * fan-out was deleted in a later commit must then vanish (tombstone skipping), not linger as a phantom witness.
	 * Cars 0, 20 and 40 are the only contributors of b0, so removing their pred2 edges must remove b0.
	 */
	@Test
	public void demotedDistinctKernelDropsSubjectsWhoseFanoutWasFullyDeleted() {
		System.setProperty("rdf4j.lmdb.wcoj.enabled", "false");
		System.setProperty("rdf4j.lmdb.factorizedRows.enabled", "false");
		System.setProperty("rdf4j.lmdb.nativeBatch.enabled", "false");
		System.setProperty("rdf4j.lmdb.packedFtree.enabled", "false");
		System.setProperty("rdf4j.lmdb.prefixRun.enabled", "false");
		System.setProperty("rdf4j.lmdb.adaptiveFilterPlacement.enabled", "false");
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI pred2 = vf.createIRI(EX, "pred2");
			conn.begin();
			for (int i : new int[] { 0, 20, 40 }) {
				conn.remove(vf.createIRI(EX, "car" + i), pred2, null);
			}
			conn.commit();
		}
		String query = distinctFanoutQuery();
		List<String> expected = genericRows(query);
		assertThat(expected).noneMatch(rowText -> rowText.contains("/b0"));
		assertThat(rows(query)).containsExactlyElementsOf(expected);
		// Same result with the demotion disabled — the transform must be invisible in the result set.
		System.setProperty("rdf4j.lmdb.janinoCodegen.distinctDeadValueDemotion", "false");
		assertThat(rows(query)).containsExactlyElementsOf(expected);
	}

	private GenericPlanNode explain(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return conn.prepareTupleQuery(query)
					.explain(Explanation.Level.Telemetry)
					.toGenericPlanNode();
		}
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(Object::toString)
					.sorted()
					.toList();
		}
	}

	private List<String> genericRows(String query) {
		String previous = System.getProperty(NATIVE_FLAG);
		try {
			System.setProperty(NATIVE_FLAG, "false");
			return rows(query);
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_FLAG);
			} else {
				System.setProperty(NATIVE_FLAG, previous);
			}
		}
	}

	private static String findMetric(GenericPlanNode node, String metricName) {
		if (node == null) {
			return null;
		}
		String value = node.getStringMetricActual(metricName);
		if (value != null) {
			return value;
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				String found = findMetric(child, metricName);
				if (found != null) {
					return found;
				}
			}
		}
		return null;
	}
}
